package de.ostms.lc.company.api;
import de.ostms.lc.audit.service.AuditService;import de.ostms.lc.company.service.CompanyProfileService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;
@RestController @RequestMapping("/api/company-profile") public class CompanyProfileController{private final CompanyProfileService service;private final AuditService audit;public CompanyProfileController(CompanyProfileService s,AuditService a){service=s;audit=a;}@GetMapping public CompanyProfileView view(){return service.view();}@PutMapping public CompanyProfileView update(@Valid @RequestBody CompanyProfileRequest request,Authentication auth){var before=service.view();var result=service.update(request,auth.getName());audit.recordChange(auth,"COMPANY_PROFILE_UPDATED","COMPANY_PROFILE",result.id(),"Firmenstammdaten geändert",before.toString(),result.toString());return result;}@PostMapping(value="/logo",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public CompanyProfileView logo(@RequestPart("file")MultipartFile file,Authentication auth)throws IOException{var result=service.logo(file,auth.getName());audit.record(auth,"COMPANY_LOGO_UPDATED","COMPANY_PROFILE",result.id(),file.getOriginalFilename());return result;}@GetMapping("/logo")public ResponseEntity<byte[]> logo(){var profile=service.profile();if(profile.getLogo()==null)return ResponseEntity.notFound().build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(profile.getLogoContentType())).body(profile.getLogo());}@DeleteMapping("/logo")@ResponseStatus(HttpStatus.NO_CONTENT)public void deleteLogo(Authentication auth){var profile=service.profile();service.deleteLogo(auth.getName());audit.record(auth,"COMPANY_LOGO_DELETED","COMPANY_PROFILE",profile.getId(),"Firmenlogo gelöscht");}}
